cd /workdir && cat > play.py << 'EOF'
import subprocess, chess, sys, time
from engine import Searcher
import engine

TLIMIT = float(sys.argv[1]) if len(sys.argv) > 1 else 40

def get_board():
    out = subprocess.run(["python3", "arena.py", "show"], capture_output=True, text=True).stdout
    return parse(out)

def parse(out):
    fen = None; moves = []
    for line in out.splitlines():
        if line.startswith("FEN:"): fen = line[4:].strip()
        if line.startswith("Moves:"):
            s = line[6:].strip()
            moves = [] if s == "(none)" else s.split()
    b = chess.Board()
    for m in moves: b.push_uci(m)
    return b, out

s = Searcher()
log = open("game.log", "a")
while True:
    b, out = get_board()
    if "Game over" in out:
        print(out, file=log, flush=True); print(out); break
    if b.turn != chess.WHITE:
        print("not our turn?", out, file=log, flush=True); break
    print(f"--- move {b.fullmove_number}, FEN {b.fen()}", file=log, flush=True)
    m, sc, d = s.best_move(b, TLIMIT, log=log)
    print(f"playing {m} score {sc} depth {d}", file=log, flush=True)
    r = subprocess.run(["python3", "arena.py", "move", m.uci()], capture_output=True, text=True)
    print(r.stdout, r.stderr, file=log, flush=True)
    if r.returncode != 0:
        print("ERROR", r.stdout, r.stderr, file=log, flush=True); break
    # prune TT occasionally to keep memory bounded
    if len(s.tt) > 3_000_000: s.tt.clear()
EOF
nohup python3 play.py 40 > play.out 2>&1 &
